        vm.mockCall(
            BUSD,
            abi.encodeWithSignature("transfer(address,uint256)"),
            abi.encode(true)
        );

        // Deploy main contract
        elon = new ELONTICKER();

        // Deploy test ERC20 token
        mockToken = new MockERC20();
        mockToken.mint(address(elon), 100 ether);
    }

    function testUncheckedRescueTransfer() public {
        // Record initial balances
        uint256 marketingBalBefore = mockToken.balanceOf(MARKETING_WALLET);
        uint256 contractBalBefore = mockToken.balanceOf(address(elon));
        console.log("Marketing balance before:", marketingBalBefore);
        console.log("Contract balance before:", contractBalBefore);

        // Perform rescue operation with failing token
        elon.rescueTokens(address(mockToken));

        // Check post-operation balances
        uint256 marketingBalAfter = mockToken.balanceOf(MARKETING_WALLET);
        uint256 contractBalAfter = mockToken.balanceOf(address(elon));
        console.log("Marketing balance after:", marketingBalAfter);
        console.log("Contract balance after:", contractBalAfter);

        // Verify balances remain unchanged despite failed transfer
        assertEq(marketingBalAfter, marketingBalBefore, "Marketing balance changed");
        assertEq(contractBalAfter, contractBalBefore, "Contract balance changed");
    }
}

contract MockFactory {}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
